import React, { useState, useEffect } from 'react';
import { Routes, Route, useNavigate } from 'react-router-dom';
import Login from './components/Login';
import Signup from './components/Signup';
import Dashboard from './components/Dashboard';
import StaffDashboard from './components/StaffDashboard';

function App() {
  const [user, setUser] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem('kid_user')) || null;
    } catch (e) {
      return null;
    }
  });

  const navigate = useNavigate();

  // 🧩 When user state changes after login/signup
  useEffect(() => {
    if (user) {
      localStorage.setItem('kid_user', JSON.stringify(user));

      // Redirect only when user just logged in or signed up
      if (window.location.pathname === '/' || window.location.pathname === '/signup') {
        if (user.role === 'staff') navigate('/staff-dashboard');
        else navigate('/dashboard');
      }
    }
  }, [user, navigate]);

  const handleLogout = () => {
    localStorage.removeItem('kid_user');
    localStorage.removeItem('token');
    localStorage.removeItem('role');
    setUser(null);
    navigate('/');
  };

  return (
    <div className="app-shell">
      <Routes>
        <Route path="/" element={<Login onLogin={setUser} />} />
        <Route path="/signup" element={<Signup onSignup={setUser} />} />
        <Route path="/dashboard" element={<Dashboard user={user} onLogout={handleLogout} />} />
        <Route path="/staff-dashboard" element={<StaffDashboard user={user} onLogout={handleLogout} />} />
      </Routes>
    </div>
  );
}

export default App;
